// Generated by scripts/photos.mjs from scripts/photos.json. Do not edit by hand.
export type Photo = {
  key: string;
  set: 'stage' | 'studio' | 'portrait';
  /** The shoot it came from; the Tony page portfolio groups by this. */
  series: string | null;
  alt: string;
  credit: string | null;
  src: string;
  width: number;
  height: number;
  blur: string;
};

export const photos: readonly Photo[] = [];

export const photo = (key: string): Photo | undefined => photos.find((p) => p.key === key);
export const photoSet = (set: Photo['set']): Photo[] => photos.filter((p) => p.set === set);
export const photoSeries = (series: string): Photo[] => photos.filter((p) => p.series === series);
